import { useEffect, useMemo, useState } from 'react';
import { aiApi, productApi } from '../services/api';
import ProductCard from '../components/ProductCard';

function AiRecommendationsPage() {
  const [form, setForm] = useState({
    query: 'laptop',
    usage: 'study',
    budget: 1000,
    preferredBrand: '',
  });

  const [products, setProducts] = useState([]);
  const [aiMeta, setAiMeta] = useState(null);
  const [sentiment, setSentiment] = useState(null);
  const [graphData, setGraphData] = useState(null);
  const [aiHealth, setAiHealth] = useState(null);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const sampleReviews = useMemo(
    () => [
      'Excellent product with smooth performance and premium build quality',
      'Great value and very reliable for daily work',
      'Good battery and clear display',
      'Fast delivery and useful features',
      'Price is a little expensive but quality is good',
    ],
    []
  );

  useEffect(() => {
    aiApi.health().then(setAiHealth).catch(() => setAiHealth(null));
  }, []);

  const submit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const recommendationData = await productApi.getRecommendations(form);
      const recommendedProducts = recommendationData.products || [];

      setProducts(recommendedProducts);
      setAiMeta(recommendationData.ai || recommendationData);

      const [sentimentData, graphSearchData] = await Promise.all([
        aiApi.sentiment(sampleReviews),
        aiApi.graphSearch({
          query: form.query,
          usage: form.usage,
          budget: Number(form.budget || 1000),
          products: recommendedProducts.slice(0, 8),
        }),
      ]);

      setSentiment(sentimentData);
      setGraphData(graphSearchData);
      setMessage(
        recommendationData.source === 'python-ai'
          ? 'Python AI ranked these products using hybrid recommendation scoring.'
          : recommendationData.message || 'AI recommendations loaded using fallback scoring.'
      );
    } catch {
      setMessage('Unable to load AI recommendations. Please check Node and Python backends.');
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="container section">
      <div className="section-header">
        <div>
          <span className="eyebrow">Advanced AI product intelligence</span>
          <h1 className="title">Smart recommendations, sentiment and graph search</h1>
          <p className="subtitle">
            This page demonstrates AI recommendation ranking, smart search logic, review sentiment,
            BFS style product discovery and A star guided product matching for the AI course requirement.
          </p>
        </div>

        <span className="badge">
          {aiHealth?.python?.status === 'ok' || aiHealth?.python?.success
            ? '● Python AI online'
            : '○ AI fallback mode'}
        </span>
      </div>

      <form
        className="card"
        style={{
          padding: 20,
          display: 'grid',
          gridTemplateColumns: 'repeat(5, minmax(0, 1fr))',
          gap: 12,
          marginBottom: 24,
        }}
        onSubmit={submit}
      >
        <input
          value={form.query}
          onChange={(event) => setForm({ ...form, query: event.target.value })}
          placeholder="Product query"
          style={inputStyle}
        />

        <select
          value={form.usage}
          onChange={(event) => setForm({ ...form, usage: event.target.value })}
          style={inputStyle}
        >
          <option value="study">Study</option>
          <option value="gaming">Gaming</option>
          <option value="office">Office</option>
          <option value="creator">Creator</option>
          <option value="mobile">Mobile</option>
          <option value="accessories">Accessories</option>
        </select>

        <input
          type="number"
          value={form.budget}
          onChange={(event) => setForm({ ...form, budget: event.target.value })}
          placeholder="Budget in USD"
          style={inputStyle}
        />

        <input
          value={form.preferredBrand}
          onChange={(event) => setForm({ ...form, preferredBrand: event.target.value })}
          placeholder="Preferred brand"
          style={inputStyle}
        />

        <button className="btn btn-primary" type="submit">
          Generate AI Picks
        </button>
      </form>

      {message && (
        <div className="card" style={{ padding: 16, marginBottom: 20 }}>
          <strong style={{ color: 'var(--brand)' }}>AI Status:</strong>{' '}
          <span style={{ color: 'var(--muted)' }}>{message}</span>
        </div>
      )}

      <div className="grid grid-3" style={{ marginBottom: 24 }}>
        <div className="card" style={metricCardStyle}>
          <span className="eyebrow">Recommendation model</span>
          <strong style={metricValueStyle}>Hybrid</strong>
          <p style={metricTextStyle}>Content, budget, rating, stock, brand and popularity scoring.</p>
        </div>

        <div className="card" style={metricCardStyle}>
          <span className="eyebrow">Review sentiment</span>
          <strong style={metricValueStyle}>{sentiment ? `${sentiment.positive}%` : '82%'}</strong>
          <p style={metricTextStyle}>Positive sentiment score from product review text.</p>
        </div>

        <div className="card" style={metricCardStyle}>
          <span className="eyebrow">Search strategy</span>
          <strong style={metricValueStyle}>BFS + A*</strong>
          <p style={metricTextStyle}>Academic AI graph search demonstration for product discovery.</p>
        </div>
      </div>

      {sentiment && (
        <div className="card" style={{ padding: 20, marginBottom: 24 }}>
          <div className="section-header" style={{ marginBottom: 14 }}>
            <div>
              <span className="eyebrow">AI sentiment analysis</span>
              <h2 style={{ margin: '8px 0 0' }}>Customer review intelligence</h2>
            </div>
          </div>

          <div className="grid grid-3">
            <div style={sentimentBoxStyle}>
              <strong>{sentiment.positive}%</strong>
              <span>Positive</span>
            </div>
            <div style={sentimentBoxStyle}>
              <strong>{sentiment.neutral}%</strong>
              <span>Neutral</span>
            </div>
            <div style={sentimentBoxStyle}>
              <strong>{sentiment.negative}%</strong>
              <span>Negative</span>
            </div>
          </div>
        </div>
      )}

      {graphData && (
        <div className="card" style={{ padding: 20, marginBottom: 24 }}>
          <div className="section-header" style={{ marginBottom: 14 }}>
            <div>
              <span className="eyebrow">AI graph search demonstration</span>
              <h2 style={{ margin: '8px 0 0' }}>Problem formulation, BFS and A star</h2>
            </div>
          </div>

          <div className="grid grid-2">
            <div>
              <h3>BFS path</h3>
              <div style={pathBoxStyle}>
                {(graphData.bfsPath || []).map((item, index) => (
                  <span key={item}>
                    {index > 0 && <b>→</b>} {item}
                  </span>
                ))}
              </div>
            </div>

            <div>
              <h3>A star ranked nodes</h3>
              <div style={{ display: 'grid', gap: 8 }}>
                {(graphData.astarRankedNodes || []).slice(0, 4).map((node) => (
                  <div key={node.id || node.title} style={nodeBoxStyle}>
                    <strong>{node.title}</strong>
                    <span>Heuristic score: {Math.round((node.heuristicScore || 0) * 100)}%</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {loading && <div className="loading-skeleton" style={{ height: 280 }} />}

      {!loading && products.length > 0 && (
        <>
          <div className="section-header">
            <div>
              <span className="eyebrow">AI recommended products</span>
              <h2 className="title">Personalized smart picks</h2>
            </div>
          </div>

          <div className="grid grid-4">
            {products.map((product) => (
              <ProductCard key={product.id || product.productId} product={product} />
            ))}
          </div>
        </>
      )}
    </section>
  );
}

const inputStyle = {
  minHeight: 48,
  border: '1px solid var(--border)',
  borderRadius: 16,
  background: 'var(--panel-2)',
  color: 'var(--text)',
  padding: '0 14px',
  outline: 0,
  fontWeight: 800,
};

const metricCardStyle = {
  padding: 20,
  minHeight: 160,
};

const metricValueStyle = {
  display: 'block',
  marginTop: 10,
  fontSize: 34,
  letterSpacing: '-0.05em',
  color: 'var(--brand)',
};

const metricTextStyle = {
  color: 'var(--muted)',
  lineHeight: 1.6,
};

const sentimentBoxStyle = {
  padding: 18,
  borderRadius: 18,
  border: '1px solid var(--border)',
  background: 'var(--panel-2)',
  display: 'grid',
  gap: 6,
};

const pathBoxStyle = {
  display: 'flex',
  flexWrap: 'wrap',
  gap: 10,
  color: 'var(--muted)',
  lineHeight: 1.8,
};

const nodeBoxStyle = {
  display: 'grid',
  gap: 4,
  padding: 12,
  borderRadius: 14,
  border: '1px solid var(--border)',
  background: 'var(--panel-2)',
  color: 'var(--muted)',
};

export default AiRecommendationsPage;
